        "allDay": false,
        "description": "Seit 2023 treffen sich member und Freunde der c-base zum gemeinsamen Wandern. Von April bis Oktober jeden Jahres bestreiten wir gru:ne Wege und Pfade in Berlin und Umgebung.\n\nDie Route f\u00fchrt uns dieses Mal vom S-Bahnhof Attilastra\u00dfe zum S-Bahnhof Gesundbrunnen \u00fcber insgesamt 16 km. Es gibt auch dieses Mal wieder die M\u00f6glichkeit, nur einen Teil der Tour mitzumachen. Mehr Details unter https://wiki.c-base.org/dokuwiki/c-hike:start\n\nEventpate: odras",
