        "allDay": false,
        "description": "Offener Stammtisch zum Thema Klemmbausteine.\nDigitales Design am Rechner mittels BrickLink Studio oder reale Implementierung mit Noppensteinen.\nEs werden eigene Entw\u00fcrfe (MOCs), Modifikationen an bestehenden Sets (MODs) und die Qualit\u00e4t der Steine und Baus\u00e4tze verschiedener Hersteller thematisiert.\nEgal ob programmierbare Roboter, ein SPACESHIP!, beleuchtete Geb\u00e4ude, Fahrzeuge oder ganz andere Welten.\n\nAb 18 Jahre!\n\npate: starpeak\n",
