        "allDay": false,
        "description": "Eventpaten: t\n\nMatrix is more than a protocol \u2014 it's a social, technical, and political project. It needs places where people can meet, exchange ideas, build software, and strengthen the community.\n\nIn a world increasingly dominated by a few Big Tech players, decentralization is not just a technical feature \u2014 it's a necessity. A connected planet deserves open protocols, community-driven infrastructure, and people who care about building a better future together.\n\nhttps://matrix-community.events/conferences/2026-summit.html",
