        "allDay": false,
        "description": "Eventpate: uhuspecht\nDay @ c-base\n\nLet`s DID it! @c-base!\n\nAm ersten Sonntag des Monats auf die gute Seite wechseln!\n\nWir unterst\u00fctzen dich dabei, deine digitale Autonomie zur\u00fcckzugewinnen. Gemeinsam und Schritt f\u00fcr Schritt. Ob von X zu Mastodon, von Google Chrome zu Firefox \u2013 wir helfen dir beim Wechsel!\n\nWarum nicht einen Email-Dienst mit mehr Privatsph\u00e4re probieren? Oder magst du bei einem Kaffee einfach mehr \u00fcber andere digitale Alternativen erfahren, die unsere Demokratie st\u00e4rken statt sie zu zerst\u00f6ren? Alternativen, die uns allen eine nachhaltige und selbstbestimmte Teilhabe sichern?\n\nDann lass uns zusammen loslegen!\n\nAm \n\n    Sonntag, 07. Juni 2026\n\n    von 14 bis 18 Uhr\n\nfreuen wir uns auf dich in der\n\n    c-base\n\n    Rungestra\u00dfe 20, 10179 Berlin\n\n\n\nEs gibt Tee, Kaffee, Snacks und nat\u00fcrlich Cookies. Lasst uns etwas f\u00fcr unsere digitale Unabh\u00e4ngigkeit tun! Kostenlos, auch ohne Vorkenntnisse. Bring aber gern deine Endger\u00e4te mit.\n\nDer Zugang und der Raum sind barrierefrei.\n\nWieder mit dabei sind als Gastgeber der Hackspace c-base, das Projekt Digital-Zebra (V\u00d6BB), Topio, der kleindatenverein, Anoxinon e.V., Computertruhe e.V. und der M\u00f6ckernkiez e.V. .\n\nSchaut aber auch gerne bei der Veranstaltung vom Chaos Computer Club Berlin e.V. und dem xHain hack+makespace vorbei.\n\nGemeinsam mehr erreichen\n\nDiese Veranstaltung ist Teil eines Netzwerks aus mehreren Organisationen und Initiativen in Berlin. Wir unterst\u00fctzen uns gegenseitig mit Kompetenz, Erfahrung und praktischer Hilfe. Uns alle eint der Wunsch, Wissen zu teilen, voneinander zu lernen und solidarisch zusammenzuarbeiten.\n\nDer DIDay  bildet dabei den gemeinsamen Rahmen, in dem wir uns f\u00fcr digitale Selbstbestimmung und nachhaltige digitale Strukturen einsetzen.\n\nSchau deshalb gern auch bei den Veranstaltungen der anderen beteiligten Organisationen vorbei. So entsteht ein vielf\u00e4ltiges Angebot, das Austausch, Vernetzung und gegenseitige Unterst\u00fctzung lebendig macht.",
