        "description": "Berlin Chaos Mesh Meetup\n\n_Meshtastic, Meshcore, Reticulum, und alles andere auf LoRa 868MHz & 433MHz._\n\nWir treffen uns **nicht** in der c-base! Diesmal nutzen wir den langen Abend, um zum Fernsehturm (und auf den M\u00fcggelturm) in den M\u00fcggelbergen zu wandern. Dort schicken wir Nachrichten in den Mesh und verstecken Nodes in der Wildness.\n\nTreffpunkt: **17:30 Uhr (p\u00fcnktlich) Stra\u00dfenbahnhaltestelle Wendenschlo\u00df** (Start 18:00 Uhr, Sonnenuntergang 21:28, D\u00e4mmerung 22:17)\n\nDetails: https://forum.chaosmesh.net/topic/66/meetup-wandertag-fernsehturm-auf-dem-gro%C3%9Fen-m%C3%BCggelberg-10.06.2026-17-30-uhr\n\nEventpate: afri\n",
