        "description": "G\u00e6mz is a hangout and community for people into art/experimental/alternative game development, playful media, and general d0peshit. It was founded in 2019 by Nomi (thenomi.com), and since 2024 has grown into regular in-person meet-ups in Tokyo, London, Taipei, and Copenhagen. There have been a few pop-up G\u00e6mz in Berlin before.\n\nEventPate: goggi",
